855	def safe_quote_json_string(text):
856	    """Return a JSON-quoted form of text with lone surrogates escaped.
857	
858	    Behaves like ``json.dumps(text, ensure_ascii=False)`` but renders each
859	    unpaired surrogate as ``\\uXXXX`` so the result is always valid,
860	    UTF-8-encodable JSON. Used when echoing caller-provided strings inside an
861	    error message, where the raw character would break error encoding.
862	    """
863	    quoted = json.dumps(text, ensure_ascii=False)
864	    return "".join(
865	        f"\\u{ord(ch):04x}" if 0xD800 <= ord(ch) <= 0xDFFF else ch
866	        for ch in quoted
867	    )
