    const rows = card.querySelectorAll('.opt-row');
    const el = rows[rows.length - 1].querySelector('.opt-text');
    el.focus(); el.value = v; fire(el);
  };
  T.removeOption = (qi, oi) => { T.cards()[qi].querySelectorAll('.opt-row')[oi].remove(); };
  T.removeQuestion = i => {
